{
  "summary": "沈知微在父亲去世后醒来，决定这一世只算自己的账。",
  "tension": 2,
  "emotions": ["suspense", "calm"],
  "hook": {"present": true, "quote": "门外忽然响起一阵轻快的脚步声，接着是一个娇滴滴的声音：‘堂姐醒了没有？我给你送姜汤来了。’"},
  "beats": [
    {
      "character": "沈知微",
      "action": "确认自己不是躺在周记当铺门外的雪地里。",
      "quote": "她盯着帐顶那块洗得发白的补丁看了很久，才确认自己不是躺在周记当铺门口的雪地里。",
      "hostile": false,
      "target": "",
      "cost": ""
    },
    {
      "character": "沈知微",
      "action": "决定这一世只算自己的账。",
      "quote": "她把玉佩塞回衣领里，在心里给自己定了规矩：这一世，她只算自己的账。谁的情都不欠，谁的亏都不吃，每一文钱都要花在刀刃上。",
      "hostile": false,
      "target": "",
      "cost": ""
    },
    {
      "character": "沈承业",
      "action": "表示要暂时管理当铺和家事。",
